package com.bank.fit;

import com.bank.fit.model.CandidateBid;
import com.bank.fit.model.JobRequirement;
import com.bank.fit.service.FitScorer;
import java.util.List;
import java.util.logging.*;

// Runnable demo: score candidate fit against role needs like a vendor bid evaluation.
public class FitDemo {
    private static final Logger log = Logger.getLogger("Fit");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // The role's real needs — the requirement checklist.
        JobRequirement role = new JobRequirement(List.of(
            "transactional correctness", "high-throughput payments",
            "incident response", "banking domain"));

        FitScorer scorer = new FitScorer(log);

        // Generic candidate — proves general skills, not the specific needs.
        CandidateBid generic = new CandidateBid("Generic", List.of(
            "java", "teamwork", "fast learner"));
        scorer.score(role, generic);

        // Tailored candidate — proves exactly the needs the role lists.
        CandidateBid tailored = new CandidateBid("Tailored", List.of(
            "transactional correctness", "high-throughput payments",
            "incident response", "banking domain", "java"));
        scorer.score(role, tailored);
    }
}
